// Landing page: the sign-in call to action must not be clipped.
await page.goto('/login');
const landingCta = page.getByRole('button', { name: /sign in|log in|get started/i }).first();
await expect(landingCta).toBeVisible();
await expect(landingCta).toHaveCSS('overflow', 'visible');
await expect(landingCta).toContainText(/\S/);

// Radar mode switch: the switch must show its full label, not a clipped one.
await page.goto('/ops/radar');
const modeSwitch = page.getByRole('radio').first();
await expect(modeSwitch).toBeVisible();
await expect(modeSwitch).toHaveCSS('overflow', 'visible');
await expect(page.getByRole('radiogroup').first()).toHaveCSS('overflow', 'visible');
